def compute(vars):
    try:
        compensation_and_benefits = vars["v1"]
        total_other_liabilities_and_accrued_expenses = vars["v2"]
        percentage = (compensation_and_benefits / total_other_liabilities_and_accrued_expenses) * 100

        return {
            "value": percentage,
            "trace": {
                "compensation_and_benefits": compensation_and_benefits,
                "total_other_liabilities_and_accrued_expenses": total_other_liabilities_and_accrued_expenses,
                "percentage": percentage,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percent"
                }
            }
        }
    except ZeroDivisionError:
        return None
